package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.common.BusinessException;import com.example.riskplatform.dto.Requests.ComplaintRequest;import com.example.riskplatform.entity.Complaint;import com.example.riskplatform.mapper.ComplaintMapper;import lombok.RequiredArgsConstructor;import com.example.riskplatform.service.rag.CorpusEvents;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class ComplaintService{private final ComplaintMapper mapper;private final DataScopeService scope;private final AuditService audit;private final CorpusEvents corpus;public List<Complaint>list(Long cid,String category){LambdaQueryWrapper<Complaint>w=new LambdaQueryWrapper<>();List<Long>ids=scope.allowedCompanyIds();if(cid!=null){if(!scope.canAccess(cid))throw new BusinessException(403,"无权访问");w.eq(Complaint::getCompanyId,cid);}else if(ids!=null){if(ids.isEmpty())return List.of();w.in(Complaint::getCompanyId,ids);}if(category!=null&&!category.isBlank())w.eq(Complaint::getCategory,category);return mapper.selectList(w.orderByDesc(Complaint::getComplaintDate).last("LIMIT 500"));}public Complaint create(ComplaintRequest r){if(!scope.canAccess(r.getCompanyId()))throw new BusinessException(403,"无权访问");Complaint x=new Complaint();BeanUtils.copyProperties(r,x);x.setComplaintNo("CP-"+System.currentTimeMillis());mapper.insert(x);corpus.upsert("complaint",x.getId(),x.getCompanyId());corpus.aggregate(x.getCompanyId());audit.log("CREATE","COMPLAINT",x.getId(),x.getCategory());return x;}}
